import React, { useState, useEffect } from "react";
import {
    Box,
    Typography,
    Button,
    TextField,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
} from "@mui/material";
import { useNavigate } from "react-router-dom";
import { ref, get, push, set } from "firebase/database";
import { db } from "./firebaseConfig";
import fondo from './fondo.jpg';

const VentaVarios = () => {
    const navigate = useNavigate();
    const [cliente, setCliente] = useState("");
    const [ventas, setVentas] = useState([]);
    const [nuevoProducto, setNuevoProducto] = useState({ nombre: "", precio: "", cantidad: "" });
    const [productosSeleccionados, setProductosSeleccionados] = useState([]);
    const [openDialog, setOpenDialog] = useState(false);

    useEffect(() => {
        cargarVentasDelMes();
    }, []);

    const cargarVentasDelMes = async () => {
        try {
            const ventasRef = ref(db, "ventas");
            const snapshot = await get(ventasRef);
            if (snapshot.exists()) {
                const data = snapshot.val();
                const mesActual = new Date().getMonth() + 1;
                const ventasFiltradas = Object.values(data).filter(
                    (venta) => new Date(venta.fecha).getMonth() + 1 === mesActual
                );
                setVentas(ventasFiltradas);
            }
        } catch (error) {
            console.error("Error al cargar las ventas:", error);
        }
    };

    const handleAgregarProducto = () => {
        if (!nuevoProducto.nombre || !nuevoProducto.precio || !nuevoProducto.cantidad) {
            alert("Ingresa nombre, precio y cantidad del producto.");
            return;
        }
        setProductosSeleccionados((prev) => [...prev, { ...nuevoProducto }]);
        setNuevoProducto({ nombre: "", precio: "", cantidad: "" });
        setOpenDialog(false);
    };

    const handleVentaSubmit = async () => {
        if (!cliente.trim()) {
            alert("Ingresa el nombre del cliente.");
            return;
        }
        if (productosSeleccionados.length === 0) {
            alert("Agrega al menos un producto a la venta.");
            return;
        }
        const totalVenta = productosSeleccionados.reduce((total, producto) => total + (parseFloat(producto.precio) * parseInt(producto.cantidad)), 0);
        try {
            const ventasRef = ref(db, "ventas");
            const nuevaVenta = push(ventasRef);
            await set(nuevaVenta, {
                cliente,
                productos: productosSeleccionados,
                fecha: new Date().toISOString(),
                descripcion: `Venta a ${cliente} con ${productosSeleccionados.length} productos. Total: $${totalVenta}`,
                total: totalVenta
            });
            setCliente("");
            setProductosSeleccionados([]);
            cargarVentasDelMes();
        } catch (error) {
            console.error("Error al registrar la venta:", error);
        }
    };

    const totalVentasMes = ventas.reduce((total, venta) => total + venta.total, 0);

    return (
        <Box sx={{ maxWidth: 800, margin: "auto", padding: 3, backgroundColor: "#f5f5f5", borderRadius: 2, boxShadow: 2, position: "relative" }}>
            <Box sx={{
                backgroundImage: `url(${fondo})`, width: '100%', height: '100%',
                backgroundRepeat: 'no-repeat',
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                mb: 5
            }}>
                <Typography
                    variant="h4"
                    component="h5"
                    textAlign={'start'}
                    sx={{ mt: 4, mb: 4, ml: 4, fontWeight: 'bold', color: '#eef' }}
                >
                    Huma Brc
                </Typography>
            </Box>
            <Typography variant="h4" textAlign="center" gutterBottom>Venta de Productos</Typography>
            <TextField fullWidth label="Nombre del Cliente" value={cliente} onChange={(e) => setCliente(e.target.value)} margin="normal" />
            <Typography variant="h6" sx={{ mt: 3 }}>Productos Seleccionados:</Typography>
            <ul>
                {productosSeleccionados.map((producto, index) => (
                    <li key={index}>{producto.nombre} - ${producto.precio} x {producto.cantidad}</li>
                ))}
            </ul>
            <Button variant="contained" color="secondary" sx={{ borderRadius: 7 }} onClick={() => setOpenDialog(true)}>Agregar Producto</Button>
            <Dialog open={openDialog} onClose={() => setOpenDialog(false)}>
                <DialogTitle>Agregar Producto</DialogTitle>
                <DialogContent>
                    <TextField label="Nombre" fullWidth value={nuevoProducto.nombre} onChange={(e) => setNuevoProducto({ ...nuevoProducto, nombre: e.target.value })} margin="normal" />
                    <TextField label="Precio" fullWidth type="number" value={nuevoProducto.precio} onChange={(e) => setNuevoProducto({ ...nuevoProducto, precio: e.target.value })} margin="normal" />
                    <TextField label="Cantidad" fullWidth type="number" value={nuevoProducto.cantidad} onChange={(e) => setNuevoProducto({ ...nuevoProducto, cantidad: e.target.value })} margin="normal" />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setOpenDialog(false)}>Cancelar</Button>
                    <Button onClick={handleAgregarProducto}>Agregar</Button>
                </DialogActions>
            </Dialog>
            <Button variant="contained" color="success" sx={{ ml: 2, borderRadius: 7 }} onClick={handleVentaSubmit}>Confirmar Venta</Button>
            <Typography variant="h5" sx={{ mt: 4 }}>Ventas del Mes</Typography>
            {ventas.length === 0 ? (
                <Typography>No hay ventas registradas este mes.</Typography>
            ) : (
                ventas.map((venta, index) => (
                    <Box key={index} sx={{ p: 2, mt: 2, border: "1px solid #ccc", borderRadius: 2 }}>
                        <Typography>{venta.descripcion} - Total: ${venta.total}</Typography>
                        <ul>
                            {venta.productos.map((producto, idx) => (
                                <li key={idx}>{producto.nombre} - ${producto.precio} x {producto.cantidad}</li>
                            ))}
                        </ul>
                    </Box>
                ))
            )}
            <Typography variant="h5" sx={{ mt: 3, textAlign: "center", borderTop: "2px solid #000", pt: 2 }}>Total de Ventas del Mes: ${totalVentasMes}</Typography>
         <Box sx={{display:'flex', justifyContent:'right', mt:4}}> 
            <Button variant="contained" sx={{borderRadius:7,  backgroundColor: "orange", color: "white", display :'flex', justifyContent:'right' }} onClick={() => navigate(-1)}>Volver</Button>
            </Box>
        </Box>
    );
};

export default VentaVarios;
