import React, { useState, useEffect } from "react";
import {
    TextField,
    Box,
    Button,
    Typography,
    List,
    ListItem,
    ListItemText,
    Checkbox,
    FormGroup,
    FormControlLabel,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
} from "@mui/material";
import { ref, get, set, push, update } from "firebase/database";
import { db } from "./firebaseConfig";
import { useNavigate } from "react-router-dom";

const Alumnos = () => {
    const [alumnos, setAlumnos] = useState([]);
    const [addDialogOpen, setAddDialogOpen] = useState(false);
    const [pagoDialogOpen, setPagoDialogOpen] = useState(false);
    const [monto, setMonto] = useState("");
    const [fechaPago, setFechaPago] = useState("");
    const [alumnoSeleccionado, setAlumnoSeleccionado] = useState(null);
    const [totalGanancias, setTotalGanancias] = useState(0);
    const navigate = useNavigate();

    useEffect(() => {
        cargarAlumnos();
    }, []);

    useEffect(() => {
        calcularTotalGanancias();
    }, [alumnos]);

    const cargarAlumnos = async () => {
        try {
            const alumnosRef = ref(db, "alumnos");
            const pagosRef = ref(db, "pagos");
            const snapshotAlumnos = await get(alumnosRef);
            const snapshotPagos = await get(pagosRef);

            let pagosData = {};
            if (snapshotPagos.exists()) {
                pagosData = snapshotPagos.val();
            }

            if (snapshotAlumnos.exists()) {
                const data = snapshotAlumnos.val();
                const alumnosList = Object.keys(data).map((key) => ({
                    ...data[key],
                    id: key,
                    pagos: pagosData[key] ? Object.values(pagosData[key]) : [],
                    clases: data[key].clases || [false, false, false, false],
                }));
                setAlumnos(alumnosList);
            }
        } catch (error) {
            console.error("Error al cargar los alumnos:", error);
        }
    };

    const calcularTotalGanancias = () => {
        const mesActual = new Date().getMonth() + 1;
        const anioActual = new Date().getFullYear();
        let total = 0;

        alumnos.forEach(alumno => {
            alumno.pagos.forEach(pago => {
                const fecha = new Date(pago.fechaPago);
                if (fecha.getMonth() + 1 === mesActual && fecha.getFullYear() === anioActual) {
                    total += pago.monto;
                }
            });
        });

        setTotalGanancias(total);
    };

    const registrarPago = async () => {
        if (!alumnoSeleccionado || !monto || !fechaPago) {
            alert("Por favor, completa todos los campos.");
            return;
        }

        try {
            const pagosRef = ref(db, `pagos/${alumnoSeleccionado.id}`);
            const nuevoPagoRef = push(pagosRef);
            await set(nuevoPagoRef, { monto: parseFloat(monto), fechaPago });

            setMonto("");
            setFechaPago("");
            setPagoDialogOpen(false);
            cargarAlumnos();
        } catch (error) {
            console.error("Error al registrar el pago:", error);
        }
    };
    const toggleClase = async (alumnoId, index) => {
        try {
            const alumno = alumnos.find((a) => a.id === alumnoId);
            if (!alumno) return;

            const nuevasClases = [...alumno.clases];
            nuevasClases[index] = !nuevasClases[index];

            await update(ref(db, `alumnos/${alumnoId}`), { clases: nuevasClases });
            setAlumnos((prevAlumnos) =>
                prevAlumnos.map((a) => (a.id === alumnoId ? { ...a, clases: nuevasClases } : a))
            );
        } catch (error) {
            console.error("Error al actualizar las clases:", error);
        }
    };
    return (
        <Box sx={{ padding: 3, display:'flex', justifyContent:'center', alignContent:'center', flexDirection:'column' }}>
        <Box sx={{display:'flex', flexDirection:'row', justifyContent:'center', alignContent:'center'}}> 
            <Button variant="contained" sx={{ borderRadius: 7, mb: 3, width:'30%' }} color="secondary" onClick={() => setAddDialogOpen(true)}>Agregar Alumno</Button>
            <Button variant="contained" color="error" sx={{ mb: 3, ml: 2, borderRadius: 7, width:'30%' }} onClick={() => navigate('/ventaVarios')}>
                Venta de Varios
            </Button>
            </Box> 
            <Typography variant="h5" gutterBottom textAlign="center">Alumnos Ingresados</Typography>
            <List >
                {alumnos.map((alumno) => (
                    <ListItem key={alumno.id} sx={{backgroundColor:'white', display: "flex", border:2, borderColor:'violet', borderRadius:4, margin:1, padding:1}}>
                        <ListItemText
                            sx={{ mb: 2 }}
                            primary={
                            <Box sx={{display:'flex', flexDirection:'row', mb:2, justifyContent:'space-around', alignContent:'center', alignItems:'center'}}>
                             <Box sx={{display:'flex', flexDirection:'column'}}> 
                                <Typography sx={{ fontWeight: "bold" }}>
                                    {`${alumno.nombre} ${alumno.apellido}`}
                                </Typography>
                                    </Box> 
                                    <Box><Typography variant="body2" color="violet">  Ingreso: {alumno.fechaIngreso}</Typography></Box>
                                    <Box sx={{ display: 'flex', flexDirection: 'row'}}>
                                        <Button color="warning" sx={{ borderRadius: 8, width:'auto' }} onClick={() => { setAlumnoSeleccionado(alumno); setPagoDialogOpen(true); }}>Nuevo Pago</Button>
                                    </Box> 
                                </Box>
                            }
                            secondary={
                                <>
                                    
                                    <Box style={{ color: "green", mt:3, display:'flex', flexDirection:'row',mb:2 }}>
                                        <strong>Pagó:</strong>
                                        {alumno.pagos.map((pago, index) => (
                                            <Box key={index}>${pago.monto} - El Día: {pago.fechaPago}</Box>
                                        ))}
                                    </Box>
                                 
                                    <FormGroup row sx={{display:'flex'}}>
                                        {alumno.clases.map((checked, index) => (
                                            <FormControlLabel
                                                key={index}
                                                control={<Checkbox checked={checked} onChange={() => toggleClase(alumno.id, index)} />}
                                                label={`Clase ${index + 1}`}
                                            />
                                        ))}
                                    </FormGroup>
                                    <Box sx={{ display: 'flex', justifyContent: 'end',mr:1 }}>
                                        <Typography variant="body" sx={{ color: 'blue' }}>Total Pagado:</Typography><Typography color="black" variant="body" fontWeight={'bold'}> ${alumno.pagos.reduce((total, pago) => total + pago.monto, 0)}</Typography>

                                    </Box>
                                </>
                            }
                        />

   
                    </ListItem>
                ))}
            </List>
          <Box sx={{backgroundColor:'lightgrey ', mt:4, padding:2, boxShadow:'4', borderRadius:7, display:'flex', justifyContent:'center', alignContent:'center', alignItems:'center'}}>
            <Typography variant="h6" color="green" sx={{mr:2}}>
                    Total de Ganancias del Mes: <Typography  variant='h4' color="red" fontWeight={'bold'}> ${totalGanancias}</Typography>
            </Typography>
            </Box>
            {/* Dialogo para registrar pagos */}
            <Dialog open={pagoDialogOpen} onClose={() => setPagoDialogOpen(false)}>
                <DialogTitle>Registrar Pago</DialogTitle>
                <DialogContent>
                    <TextField label="Monto" type="number" fullWidth value={monto} onChange={(e) => setMonto(e.target.value)} margin="dense" />
                    <TextField label="Fecha de Pago" type="date" fullWidth InputLabelProps={{ shrink: true }} value={fechaPago} onChange={(e) => setFechaPago(e.target.value)} margin="dense" />
                </DialogContent>
                <DialogActions>
                    <Button onClick={() => setPagoDialogOpen(false)}>Cancelar</Button>
                    <Button onClick={registrarPago} color="primary" variant="contained">Confirmar Pago</Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
};

export default Alumnos;
